// elements-of-style plugin for OpenCode — registers the skills directory.
// GENERATED by everyharness — edit everyharness.yaml instead

import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

// Minimal frontmatter stripper (dependency-free rather than pulling in a
// markdown/frontmatter package for a single bootstrap-file read).
const extractAndStripFrontmatter = (content) => {
  const match = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/)
  if (!match) return { frontmatter: {}, content }
  const frontmatterStr = match[1]
  const body = match[2]
  const frontmatter = {}
  for (const line of frontmatterStr.split('\n')) {
    const colonIdx = line.indexOf(':')
    if (colonIdx > 0) {
      const key = line.slice(0, colonIdx).trim()
      const value = line.slice(colonIdx + 1).trim().replace(/^["']|["']$/g, '')
      frontmatter[key] = value
    }
  }
  return { frontmatter, content: body }
}

const skillsDir = path.resolve(__dirname, '../../skills')

export const ElementsOfStylePlugin = async ({ client, directory }) => {
  return {
    // Inject the plugin's skills path into live config so OpenCode discovers
    // its skills without requiring manual symlinks or config file edits.
    config: async (config) => {
      config.skills = config.skills || {}
      config.skills.paths = config.skills.paths || []
      if (!config.skills.paths.includes(skillsDir)) {
        config.skills.paths.push(skillsDir)
      }
    },
  }
}

// V2 entry point. V1 also calls default.setup, but with a ctx lacking the
// skill/session domains; the named export already serves V1, so bail out.
async function setup(ctx) {
  if (!ctx || !ctx.skill || typeof ctx.skill.transform !== 'function') return

  try {
    const skills = []
    if (fs.existsSync(skillsDir)) {
      for (const entry of fs.readdirSync(skillsDir, { withFileTypes: true })) {
        if (!entry.isDirectory() || entry.name.startsWith('.')) continue
        const skillPath = path.join(skillsDir, entry.name, 'SKILL.md')
        if (!fs.existsSync(skillPath)) continue
        const { frontmatter, content } = extractAndStripFrontmatter(fs.readFileSync(skillPath, 'utf8'))
        skills.push({
          id: entry.name,
          name: frontmatter.name || entry.name,
          ...(frontmatter.description ? { description: frontmatter.description } : {}),
          path: skillPath,
          content,
        })
      }
    }
    await ctx.skill.transform((draft) => {
      for (const skill of skills) {
        try {
          draft.add(skill)
        } catch (err) {
          // A throw escaping the transform hard-disables the whole plugin; skip the skill instead.
          console.error('[elements-of-style] skill "' + skill.id + '" rejected by host, skipping:', err)
        }
      }
    })
  } catch (err) {
    console.error('[elements-of-style] skill registration failed:', err)
  }

}

export default {
  id: 'elements-of-style',
  server: ElementsOfStylePlugin,
  setup,
}
